{"items":[{"id":"cap-v2-replacement-numeric_reasoning-java-repair-01","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testNormalScalingAndFlooring();
        testClampingAtBothBounds();
        testLargeIntermediateProducts();
        testBoundaryParameters();
        testEmptyInputAndFreshArray();
        testInputIsNotModified();
        testDeterministicIndependentResults();
    }

    private static void testNormalScalingAndFlooring() {
        int[] actual = Solution.scaleReadings(
                new int[]{0, 1, 2, 3, 10}, 3, 2, 0, 100);
        assertArrayEquals(new int[]{0, 1, 3, 4, 15}, actual,
                "normal scaling must use floor division");
    }

    private static void testClampingAtBothBounds() {
        int[] actual = Solution.scaleReadings(
                new int[]{0, 1, 4, 10, 100}, 2, 3, 3, 20);
        assertArrayEquals(new int[]{3, 3, 3, 6, 20}, actual,
                "values must be clamped to both inclusive bounds");
    }

    private static void testLargeIntermediateProducts() {
        int[] actual = Solution.scaleReadings(
                new int[]{1_000_000_000, 999_999_999, 500_000_000},
                1_000_000_000,
                1_000_000_000,
                0,
                1_000_000_000);
        assertArrayEquals(
                new int[]{1_000_000_000, 999_999_999, 500_000_000},
                actual,
                "multiplication must remain correct beyond the int range");

        int[] floored = Solution.scaleReadings(
                new int[]{999_999_999},
                999_999_999,
                1_000_000_000,
                0,
                1_000_000_000);
        assertArrayEquals(new int[]{999_999_998}, floored,
                "large products must still be divided and floored exactly");
    }

    private static void testBoundaryParameters() {
        assertArrayEquals(
                new int[]{7, 7, 7},
                Solution.scaleReadings(
                        new int[]{0, 1, 1_000_000_000}, 0, 1, 7, 9),
                "zero numerator must produce zero before lower clamping");

        assertArrayEquals(
                new int[]{0, 1_000_000_000},
                Solution.scaleReadings(
                        new int[]{0, 1_000_000_000}, 1, 1, 0, 1_000_000_000),
                "extreme permitted readings and bounds must be supported");

        assertArrayEquals(
                new int[]{42, 42},
                Solution.scaleReadings(
                        new int[]{0, 1_000_000_000}, 1_000_000_000, 1, 42, 42),
                "equal lower and upper bounds must force every result to that bound");
    }

    private static void testEmptyInputAndFreshArray() {
        int[] input = new int[0];
        int[] result = Solution.scaleReadings(input, 5, 2, 0, 100);
        assertArrayEquals(new int[0], result, "empty input must produce empty output");
        assertTrue(result != input, "empty output must not alias the input array");
    }

    private static void testInputIsNotModified() {
        int[] input = {2, 7, 11};
        int[] snapshot = input.clone();
        int[] result = Solution.scaleReadings(input, 4, 3, 0, 100);

        assertArrayEquals(snapshot, input, "the input array must not be modified");
        assertTrue(result != input, "the returned array must be a new array");

        result[0] = 99;
        assertArrayEquals(snapshot, input,
                "mutating the returned array must not affect the input array");
    }

    private static void testDeterministicIndependentResults() {
        int[] input = {1, 5, 9};
        int[] first = Solution.scaleReadings(input, 7, 4, 0, 100);
        int[] second = Solution.scaleReadings(input, 7, 4, 0, 100);

        assertArrayEquals(new int[]{1, 8, 15}, first,
                "repeated calls must produce the specified values");
        assertArrayEquals(first, second, "repeated calls must be stable");
        assertTrue(first != second, "each call must return a distinct new array");
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected "
                    + Arrays.toString(expected) + " but got " + Arrays.toString(actual));
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
"}]}

